def subterms(x):
    out = []
    todo = [x]
    while todo:
        y = todo.pop()
        if isinstance(y, list) and y:
            out.append(y)
            i = 1
            while i < len(y):
                if isinstance(y[i], list):
                    todo.append(y[i])
                i += 1
    return out

def has_tag(x, name):
    for y in subterms(x):
        if y[0] == name:
            return True
    return False

def owner_ok(x):
    if not isinstance(x, list) or not x:
        return False
    return x[0] in ('receiving_party', 'party', 'named_recipient')

def class_tags(x, defs):
    tags = set()
    todo = [x]
    seen = set()
    while todo:
        y = todo.pop()
        if not isinstance(y, list) or not y:
            continue
        n = y[0]
        if n == 'representatives_of':
            k = str(y[1]) if len(y) > 1 else ''
            if k not in seen:
                seen.add(k)
                for d in defs:
                    if str(d[0]) == k or (isinstance(d[0], list) and d[0] and (d[0][0] == 'party')):
                        todo.append(d[1])
            continue
        if n == 'internal_personnel_of' and len(y) > 1 and owner_ok(y[1]):
            tags.add('employees_of')
        if n in ('employees_of', 'directors_of', 'officers_of', 'legal_advisors_of', 'financial_advisors_of', 'professional_advisors_of', 'accountants_of', 'consultants_of', 'agents_of', 'independent_contractors_of', 'lenders_of'):
            if len(y) > 1 and owner_ok(y[1]):
                tags.add(n)
            continue
        if n == 'third_parties':
            tags.add(n)
            continue
        i = 1
        while i < len(y):
            if isinstance(y[i], list):
                todo.append(y[i])
            i += 1
    return tags

def unique(xs):
    out = []
    for x in xs:
        if x not in out:
            out.append(x)
    return out

def apply(inputs, premises):
    task = inputs.get('task_id')
    if task not in ('nda-5', 'nda-7', 'nda-16', 'nda-20'):
        return {'handled': False, 'answer': None, 'used_nodes': []}
    nodes = premises.get('nodes', [])
    roots = premises.get('roots', [])
    byid = {}
    for n in nodes:
        byid[n.get('id')] = n
    entries = []
    for root in roots:
        todo = [root]
        seen = set()
        while todo:
            nid = todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node = byid[nid]
            for t in subterms(node.get('term')):
                entries.append((t, root))
            for c in node.get('child_ids', []):
                todo.append(c)
    if task in ('nda-5', 'nda-7'):
        return disclosure_decision(task, entries)
    disposal = []
    retention_yes = []
    retention_no = []
    for t, r in entries:
        if t[0] == 'disposal_obligation' and len(t) == 5:
            disposal.append((t, r))
        elif t[0] in ('retention_permission', 'retention_exception'):
            retention_yes.append(r)
        elif t[0] == 'retention_prohibition':
            retention_no.append(r)
    if task == 'nda-16':
        relevant = []
        entailed = []
        for t, r in disposal:
            action = t[2]
            trigger = t[3]
            if has_tag(action, 'return_to') or has_tag(action, 'destroy'):
                relevant.append(r)
                if has_tag(trigger, 'agreement_termination') or has_tag(trigger, 'service_termination') or has_tag(trigger, 'purpose_completion') or has_tag(trigger, 'relationship_endpoint'):
                    entailed.append(r)
        if entailed:
            return {'handled': True, 'answer': 'Entailment', 'used_nodes': unique(entailed)}
        if relevant:
            return {'handled': True, 'answer': 'NotMentioned', 'used_nodes': unique(relevant)}
        return {'handled': False, 'answer': None, 'used_nodes': []}
    if retention_yes:
        return {'handled': True, 'answer': 'Entailment', 'used_nodes': unique(retention_yes)}
    if retention_no:
        return {'handled': True, 'answer': 'Contradiction', 'used_nodes': unique(retention_no)}
    relevant = []
    contrary = []
    for t, r in disposal:
        action = t[2]
        exceptions = t[4]
        if not (has_tag(action, 'return_to') or has_tag(action, 'destroy')):
            continue
        relevant.append(r)
        if has_tag(action, 'confidential_information') and has_tag(action, 'copies_of') and (exceptions == ['no_exceptions']):
            contrary.append(r)
    if contrary:
        return {'handled': True, 'answer': 'Contradiction', 'used_nodes': unique(contrary)}
    if relevant:
        return {'handled': True, 'answer': 'NotMentioned', 'used_nodes': unique(relevant)}
    return {'handled': False, 'answer': None, 'used_nodes': []}

def disclosure_decision(task, entries):
    defs = []
    def_roots = []
    for t, r in entries:
        if t[0] == 'define_representative' and len(t) == 3:
            defs.append((t[1], t[2]))
            def_roots.append(r)
    permissions = []
    prohibitions = []
    relevant = []
    for t, r in entries:
        if t[0] not in ('permission', 'prohibition') or len(t) < 3:
            continue
        action = t[2]
        if not isinstance(action, list) or len(action) != 3 or action[0] != 'disclose':
            continue
        if not has_tag(action[1], 'confidential_information'):
            continue
        relevant.append(r)
        tags = class_tags(action[2], defs)
        item = (r, tags, action[2])
        if t[0] == 'permission':
            permissions.append(item)
        else:
            prohibitions.append(item)
    relevant = unique(relevant)
    if not relevant:
        return {'handled': False, 'answer': None, 'used_nodes': []}
    wanted = {'employees_of'} if task == 'nda-5' else {'third_parties', 'consultants_of', 'agents_of', 'legal_advisors_of', 'financial_advisors_of', 'professional_advisors_of', 'accountants_of', 'independent_contractors_of'}
    for r, tags, recipient in permissions:
        if tags.intersection(wanted):
            used = [r]
            if has_tag(recipient, 'representatives_of'):
                used.extend(def_roots)
            return {'handled': True, 'answer': 'Entailment', 'used_nodes': unique(used)}
    for r, tags, recipient in prohibitions:
        if has_tag(recipient, 'outsiders_to'):
            continue
        if tags.intersection(wanted):
            return {'handled': True, 'answer': 'Contradiction', 'used_nodes': [r]}
    return {'handled': True, 'answer': 'NotMentioned', 'used_nodes': unique(relevant + def_roots)}
